  "implementation": "import math

def solve(case):
    matrix = case['matrix']
    n_rows = len(matrix)
    if n_rows == 0:
        raise ValueError("empty matrix")
    n_features = len(matrix[0])
    if n_features == 0:
        raise ValueError("empty row")
    for row in matrix:
        if len(row) != n_features:
            raise ValueError("non-rectangular matrix")
    df = [0] * n_features
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    idf_raw = [math.log(1 + n_rows / (1 + d)) for d in df]
    idf = [round(v, 6) for v in idf_raw]
    weighted_matrix = []
    row_degree = []
    for row in matrix:
        weighted_row = [row[j] * idf_raw[j] for j in range(n_features)]
        deg = sum(weighted_row)
        weighted_matrix.append([round(v, 6) for v in weighted_row])
        row_degree.append(round(deg, 6))
    return {
        'idf': idf,
        'row_degree': row_degree,
        'weighted_matrix': weighted_matrix
    }"
}
